function parseCategory(
  category: EmojiCategoryId,
): readonly EmojiCatalogEntry[] {
  return emojiData[category]
    .slice(0, -RECORD_SEPARATOR.length)
    .split(RECORD_SEPARATOR)
    .map((record) => {
      const [emoji, label, searchText] = record.split(FIELD_SEPARATOR);
      return { emoji, label, searchText, category };
    });
}

export const emojiCatalogByCategory = Object.fromEntries(
  emojiCategories.map((category) => [category.id, parseCategory(category.id)]),
) as Record<EmojiCategoryId, readonly EmojiCatalogEntry[]>;

export const emojiCatalog: readonly EmojiCatalogEntry[] =
  emojiCategories.flatMap((category) => emojiCatalogByCategory[category.id]);
